            "x64"
          ]
        },
        {
          "target": "zip",
          "arch": [
            "x64"
          ]
        }
      ]
    },
    "nsis": {
      "artifactName": "${productName}-Setup-${version}.${ext}",
      "oneClick": true,
      "perMachine": false
    },
    "publish": {
      "provider": "generic",
      "url": "https://nodeterm.dev/updates"
    }
  },
